 function resetMouseView(){if(held){held.group.position.set(0,-.16,-1.03);held.group.rotation.set(...(held.def.inspectRotation||[0,0,0]));toast('Artifact view reset.');}else{if(mode==='cardboard')viewerFit.set({...fitSettings,fov:85});else{landscapeFov=72;camera.fov=landscapeFov;camera.updateProjectionMatrix();}recenter();toast('View size reset and recentered.');}}
