  if(held){const result=constrainInspection(C.wheelPixels(e.deltaY,e.deltaMode,innerHeight));toast(result.atLimit?'Closest view · stopped before the surface':'Artifact zoom: '+(1.03/result.distance).toFixed(1)+'× · click wheel to reset');return;}
  if(mode==='cardboard')viewerFit.set(C.viewerWheel(fitSettings,'fov',e.deltaY,e.deltaMode,innerHeight));else{landscapeFov=C.viewerWheel({fov:landscapeFov},'fov',e.deltaY,e.deltaMode,innerHeight).fov;camera.fov=landscapeFov;camera.updateProjectionMatrix();}
